using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Text;using System.Text.Json;using MassiveArmy.Industrial;
class MiningBenchmark {
 static FramePose P(double x,double z=0)=>new FramePose{body=1,y=100000,x=x,z=z};
 static IndustrialMachine M(IndustrialWorld w,string type,FramePose pose){var m=new IndustrialMachine{id=w.AllocateId(),owner=1,definition=type,recipe=IndustrialCatalog.Machines[type].recipe,pose=pose,input=new Inventory{capacity=1000000},output=new Inventory{capacity=1000000}};w.machines.Add(m);return m;}
 static void Job(IndustrialWorld w,IndustrialMachine vehicle,long source,long target,string role){var owner=w.Actor(1);owner.pose=vehicle.pose;owner.pose.z+=9;var c=IndustrialHaulNavigation.Plan(w,1,vehicle.id,source,target,null,out var error,false,role);if(c==null)throw new Exception(error);c.sequence=owner.lastSequence+1;c.operationRole=role;c.item="vehicle-operation";var r=w.Execute(1,c);if(!r.accepted)throw new Exception(r.message);owner.pose=P(-1000,-1000);}
 static void Main(string[] args){string mode=args[1];var w=new IndustrialWorld();for(int i=1;i<=16;i++)w.Register(i,P(-1000-i*2,-1000));var vehicles=new List<IndustrialMachine>();var processors=new List<IndustrialMachine>();var receiving=new List<IndustrialMachine>();var sources=new List<SurfaceDeposit>();var jobs=new List<(IndustrialMachine,long,long,string)>();
 if(mode=="team"){
  for(int i=0;i<50;i++){double x=i%10*150,z=i/10*150;var d=M(w,"excavator",P(x,z-7));d.input.capacity=1000;d.input.Add("fuel",100);var t=M(w,"truck",P(x-20,z-20));t.input.capacity=1000;t.input.Add("fuel",100);vehicles.AddRange(new[]{d,t});var store=M(w,"store",P(x+60,z));receiving.Add(store);var node=new SurfaceDeposit{id=w.AllocateId(),pose=P(x,z),remaining=new MaterialLot{litres=1000000,iron=200000,copper=100000}};w.deposits.Add(node);sources.Add(node);jobs.Add((d,node.id,store.id,"excavate"));jobs.Add((t,node.id,store.id,"transport"));}
  for(int i=0;i<50;i++)M(w,"store",P(7000+i*6,7000));long generatorId=w.nextId;
  for(int i=0;i<900;i++){string id=i<100?"generator":i<400?"foundry":i<700?"press":"store";var m=M(w,id,P(5000+i%32*6,5000+i/32*6));m.powerSource=generatorId+i%100;if(id=="generator")m.input.Add("fuel",10000);if(id=="foundry")m.input.Add("iron-ore",40000);if(id=="press")m.input.Add("iron-bar",40000);}
 }else if(mode=="waste"){
  for(int i=0;i<100;i++){double x=i%10*150,z=i/10*150;var g=M(w,"generator",P(x-12,z+12));g.input.Add("fuel",10000);var s=M(w,"sluice",P(x,z));s.powerSource=g.id;s.water=10000;s.input.bulk=new MaterialLot{litres=100000,iron=20000};processors.Add(s);var l=M(w,"loader",P(x+15,z-15));l.input.capacity=1000;l.input.Add("fuel",100);vehicles.Add(l);}
  for(int i=0;i<800;i++)M(w,"store",P(5000+i%32*6,5000+i/32*6));
 }else throw new Exception("Use team or waste");
 w.EnableMiningWorkflow();var planning=Stopwatch.StartNew();if(mode=="waste"){using(var a=new IndustrialAuthority(w)){for(int i=0;i<100;i++){var s=processors[i];var p=s.pose;p.x+=40;string error=a.CreateTailingsDump(s.id,p);if(error!=null)throw new Exception(error);Job(w,vehicles[i],s.id,s.tailingsDump,"tailings");}}}else foreach(var j in jobs)Job(w,j.Item1,j.Item2,j.Item3,j.Item4);planning.Stop();
 var coldSave=Stopwatch.StartNew();string warm=IndustrialAuthority.Snapshot(w);coldSave.Stop();var coldLoad=Stopwatch.StartNew();IndustrialAuthority.Restore(warm);coldLoad.Stop();for(int i=0;i<600;i++)w.Step();GC.Collect();GC.WaitForPendingFinalizers();var samples=new double[3000];var watch=Stopwatch.StartNew();for(int i=0;i<samples.Length;i++){long t=Stopwatch.GetTimestamp();w.Step();samples[i]=Stopwatch.GetElapsedTime(t).TotalMilliseconds;}watch.Stop();Array.Sort(samples);
 int active=vehicles.Count(v=>v.haul.active);long delivered=mode=="team"?receiving.Sum(s=>s.input.bulk.litres):w.piles.Sum(p=>p.Volume),remaining=mode=="team"?sources.Sum(s=>s.remaining.litres):processors.Sum(s=>s.input.bulk.litres);if(w.machines.Count!=1100||active!=100||vehicles.Any(v=>v.haul.status.Contains("Needs fuel")))throw new Exception("Population, operation or fuel failure");if(mode=="team"&&delivered<100000)throw new Exception("Team stopped hauling");if(mode=="waste"&&remaining>=9000000)throw new Exception("Cleanup stress failed to process material");
 if(mode=="team"){long accounted=remaining+vehicles.Sum(v=>v.input.bulk.litres)+receiving.Sum(m=>m.input.bulk.litres);if(accounted!=50000000)throw new Exception("Team material conservation failure");}else{long ore=processors.Sum(m=>m.output.Count("iron-ore")),waste=processors.Sum(m=>IndustrialWorld.TailingsCount(m.frontTailings))+vehicles.Sum(v=>IndustrialWorld.TailingsCount(v.input))+w.piles.Sum(p=>p.Volume);if(remaining+ore+waste!=10000000||waste!=(10000000-remaining)*8/10||w.piles.Any(p=>p.cells.Sum()!=p.Volume))throw new Exception("Waste conservation or pile geometry failure");}
 var save=Stopwatch.StartNew();string snapshot=IndustrialAuthority.Snapshot(w);save.Stop();var load=Stopwatch.StartNew();var restored=IndustrialAuthority.Restore(snapshot);load.Stop();if(restored.machines.Count!=1100)throw new Exception("Recovery lost machines");var process=Process.GetCurrentProcess();var result=new{scope="Standalone industrial CPU only. Different roles/scenarios are reported separately; not equivalent throughput or full Unity/GPU acceptance.",mode,stationaryMachines=1000,vehicles=100,activeJobs=active,excavators=vehicles.Count(v=>v.definition=="excavator"),trucks=vehicles.Count(v=>v.definition=="truck"),loaders=vehicles.Count(v=>v.definition=="loader"),activeSluices=processors.Count(s=>s.status=="Washing · tailings discharged at front"),fullRateProcessing=mode!="waste"||remaining==6400000,processingUtilization=mode=="waste"?(10000000-remaining)/3600000d:1,oreFraction=mode=="waste"?.2:0,ticks=samples.Length,deliveredLitres=delivered,remainingRawLitres=remaining,medianMs=samples[1500],p95Ms=samples[2850],simulationTicksPerSecond=samples.Length/watch.Elapsed.TotalSeconds,planningTotalMs=planning.Elapsed.TotalMilliseconds,processPrivateBytes=process.PrivateMemorySize64,workingSetBytes=process.WorkingSet64,managedBytes=GC.GetTotalMemory(false),snapshotBytes=Encoding.UTF8.GetByteCount(snapshot),coldSaveMs=coldSave.Elapsed.TotalMilliseconds,coldLoadMs=coldLoad.Elapsed.TotalMilliseconds,saveMs=save.Elapsed.TotalMilliseconds,loadMs=load.Elapsed.TotalMilliseconds};Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(args[0])));File.WriteAllText(args[0],JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));
 }
}


